{
  "name": "梅特勒-托利多实验室天平",
  "name_en": "Mettler Toledo laboratory balance",
  "manufacturer": "Mettler Toledo",
  "description": "实验室电子天平，用于对样品、试剂或容器进行高精度称量。该类天平通常支持去皮、清零和读取重量，适用于分析称量、配液配样及常规质量测量。",
  "description_en": "An electronic laboratory balance used for precise weighing of samples, reagents, and containers. This type of balance typically supports tare, zeroing, and weight readout, and is used for analytical weighing, sample preparation, and routine mass measurements in the lab.",
  "actions": [
    {
      "action_name": "auto-clear_tare",
      "description": "清除去皮值。",
      "description_en": "Clear the tare value."
    },
    {
      "action_name": "auto-name",
      "description": "获取/设置天平名称。",
      "description_en": "Get/set the balance name."
    },
    {
      "action_name": "auto-query",
      "description": "向天平发送 MT-SICS 命令并读取响应。",
      "description_en": "Send an MT-SICS command to the balance and read the response."
    },
    {
      "action_name": "auto-reset",
      "description": "复位天平。",
      "description_en": "Reset the balance."
    },
    {
      "action_name": "auto-tare",
      "description": "对天平执行去皮。",
      "description_en": "Tare the balance."
    },
    {
      "action_name": "auto-tare_value",
      "description": "获取/设置去皮值。",
      "description_en": "Get/set the tare value."
    },
    {
      "action_name": "auto-weight_mode",
      "description": "获取/设置称量模式。",
      "description_en": "Get/set the weighing mode."
    },
    {
      "action_name": "auto-zero",
      "description": "对天平执行清零。",
      "description_en": "Zero the balance."
    },
    {
      "action_name": "auto-mt_sics",
      "description": "获取 MT-SICS 级别和版本信息。",
      "description_en": "Get the MT-SICS level and version information."
    },
    {
      "action_name": "auto-mt_sics_commands",
      "description": "获取支持的 MT-SICS 命令列表。",
      "description_en": "Get the list of supported MT-SICS commands."
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取序列号。",
      "description_en": "Get the serial number."
    },
    {
      "action_name": "auto-weight",
      "description": "获取当前重量。",
      "description_en": "Get the current weight."
    }
  ],
  "tag_hints": [
    "laboratory balance",
    "precision weighing",
    "analytical weighing",
    "tare and zero",
    "mass measurement",
    "MT-SICS",
    "electronic balance"
  ]
}

